import { Effect, Schema as S } from "effect"

export const UploadConfigSchema = S.Struct({
  bucket: S.String,
  keyPrefix: S.String,
  parallelUploads: S.optionalKey(S.Int)
})

export type UploadConfig = typeof UploadConfigSchema.Encoded

export interface Artifact {
  readonly name: string
  readonly bytes: Uint8Array
}

export const loadUploadConfig = (moduleUrl: string) =>
  Effect.gen(function*() {
    const module = yield* Effect.tryPromise({
      try: () => import(moduleUrl),
      catch: (cause) => new Error(`Cannot load upload configuration: ${String(cause)}`)
    })
    const input: unknown = module.default
    return yield* S.decodeUnknownEffect(UploadConfigSchema)(input)
  })

export const uploadArtifacts = (
  moduleUrl: string,
  artifacts: ReadonlyArray<Artifact>,
  upload: (bucket: string, key: string, bytes: Uint8Array) => Promise<void>
) =>
  Effect.gen(function*() {
    const config = yield* loadUploadConfig(moduleUrl)
    yield* Effect.forEach(
      artifacts,
      (artifact) => Effect.tryPromise({
        try: () => upload(config.bucket, `${config.keyPrefix}/${artifact.name}`, artifact.bytes),
        catch: (cause) => new Error(`Upload failed for ${artifact.name}: ${String(cause)}`)
      }),
      { concurrency: config.parallelUploads ?? 4, discard: true }
    )
  })

